40	/**
41	 * A {@link Bootstrap} that makes it easy to bootstrap a {@link Channel} to use
42	 * for clients.
43	 *
44	 * <p>The {@link #bind()} methods are useful in combination with connectionless transports such as datagram (UDP).
45	 * For regular TCP connections, please use the provided {@link #connect()} methods.</p>
46	 */
47	public class Bootstrap extends AbstractBootstrap<Bootstrap, Channel> {
48	
49	    private static final InternalLogger logger = InternalLoggerFactory.getInstance(Bootstrap.class);
50	
51	    private final BootstrapConfig config = new BootstrapConfig(this);
52	
53	    private ExternalAddressResolver externalResolver;
54	    private volatile boolean disableResolver;
55	    private volatile SocketAddress remoteAddress;
56	
57	    public Bootstrap() { }
58	
59	    private Bootstrap(Bootstrap bootstrap) {
60	        super(bootstrap);
61	        externalResolver = bootstrap.externalResolver;
62	        disableResolver = bootstrap.disableResolver;
63	        remoteAddress = bootstrap.remoteAddress;
64	    }
65	
66	    /**
67	     * Sets the {@link NameResolver} which will resolve the address of the unresolved named address.
68	     *
69	     * @param resolver the {@link NameResolver} for this {@code Bootstrap}; may be {@code null}, in which case a default
70	     *                 resolver will be used
71	     *
72	     * @see io.netty.resolver.DefaultAddressResolverGroup
73	     */
74	    public Bootstrap resolver(AddressResolverGroup<?> resolver) {
75	        externalResolver = resolver == null ? null : new ExternalAddressResolver(resolver);
76	        disableResolver = false;
77	        return this;
78	    }
79	
80	    /**
81	     * Disables address name resolution. Name resolution may be re-enabled with
82	     * {@link Bootstrap#resolver(AddressResolverGroup)}
83	     */
84	    public Bootstrap disableResolver() {
85	        externalResolver = null;
86	        disableResolver = true;
87	        return this;
88	    }
89	
90	    /**
91	     * The {@link SocketAddress} to connect to once the {@link #connect()} method
92	     * is called.
93	     */
94	    public Bootstrap remoteAddress(SocketAddress remoteAddress) {
95	        this.remoteAddress = remoteAddress;
96	        return this;
97	    }
98	
99	    /**
100	     * @see #remoteAddress(SocketAddress)
101	     */
102	    public Bootstrap remoteAddress(String inetHost, int inetPort) {
103	        remoteAddress = InetSocketAddress.createUnresolved(inetHost, inetPort);
104	        return this;
105	    }
106	
107	    /**
108	     * @see #remoteAddress(SocketAddress)
109	     */
110	    public Bootstrap remoteAddress(InetAddress inetHost, int inetPort) {
111	        remoteAddress = new InetSocketAddress(inetHost, inetPort);
112	        return this;
113	    }
114	
115	    /**
116	     * Connect a {@link Channel} to the remote peer.
117	     */
118	    public ChannelFuture connect() {
119	        validate();
120	        SocketAddress remoteAddress = this.remoteAddress;
121	        if (remoteAddress == null) {
122	            throw new IllegalStateException("remoteAddress not set");
123	        }
124	
125	        return doResolveAndConnect(remoteAddress, config.localAddress());
126	    }
127	
128	    /**
129	     * Connect a {@link Channel} to the remote peer.
130	     */
131	    public ChannelFuture connect(String inetHost, int inetPort) {
132	        return connect(InetSocketAddress.createUnresolved(inetHost, inetPort));
133	    }
134	
135	    /**
136	     * Connect a {@link Channel} to the remote peer.
137	     */
138	    public ChannelFuture connect(InetAddress inetHost, int inetPort) {
139	        return connect(new InetSocketAddress(inetHost, inetPort));
140	    }
141	
142	    /**
143	     * Connect a {@link Channel} to the remote peer.
144	     */
145	    public ChannelFuture connect(SocketAddress remoteAddress) {
146	        ObjectUtil.checkNotNull(remoteAddress, "remoteAddress");
147	        validate();
148	        return doResolveAndConnect(remoteAddress, config.localAddress());
149	    }
150	
151	    /**
152	     * Connect a {@link Channel} to the remote peer.
153	     */
154	    public ChannelFuture connect(SocketAddress remoteAddress, SocketAddress localAddress) {
155	        ObjectUtil.checkNotNull(remoteAddress, "remoteAddress");
156	        validate();
157	        return doResolveAndConnect(remoteAddress, localAddress);
158	    }
159	
160	    /**
161	     * @see #connect()
162	     */
163	    private ChannelFuture doResolveAndConnect(final SocketAddress remoteAddress, final SocketAddress localAddress) {
164	        final ChannelFuture regFuture = initAndRegister();
165	        final Channel channel = regFuture.channel();
166	
167	        if (regFuture.isDone()) {
168	            if (!regFuture.isSuccess()) {
169	                return regFuture;
170	            }
171	            return doResolveAndConnect0(channel, remoteAddress, localAddress, channel.newPromise());
172	        } else {
173	            // Registration future is almost always fulfilled already, but just in case it's not.
174	            final PendingRegistrationPromise promise = new PendingRegistrationPromise(channel);
175	            regFuture.addListener(future -> {
176	                // Directly obtain the cause and do a null check so we only need one volatile read in case of a
177	                // failure.
178	                Throwable cause = future.cause();
179	                if (cause != null) {
180	                    // Registration on the EventLoop failed so fail the ChannelPromise directly to not cause an
181	                    // IllegalStateException once we try to access the EventLoop of the Channel.
182	                    promise.setFailure(cause);
183	                } else {
184	                    // Registration was successful, so set the correct executor to use.
185	                    // See https://github.com/netty/netty/issues/2586
186	                    promise.registered();
187	                    doResolveAndConnect0(channel, remoteAddress, localAddress, promise);
188	                }
189	            });
190	            return promise;
191	        }
192	    }
193	
194	    private ChannelFuture doResolveAndConnect0(final Channel channel, SocketAddress remoteAddress,
195	                                               final SocketAddress localAddress, final ChannelPromise promise) {
196	        // The Channel was created and registered before the address resolution started. Close it if the connect
197	        // attempt fails or is cancelled while resolution is still in progress.
198	        promise.addListener(ChannelFutureListener.CLOSE_ON_FAILURE);
199	        if (promise.isDone()) {
200	            return promise;
201	        }
202	
203	        try {
204	            if (disableResolver) {
205	                doConnect(remoteAddress, localAddress, promise);
206	                return promise;
207	            }
208	
209	            final EventLoop eventLoop = channel.eventLoop();
210	            AddressResolver<SocketAddress> resolver;
211	            try {
212	                resolver = ExternalAddressResolver.getOrDefault(externalResolver).getResolver(eventLoop);
213	            } catch (Throwable cause) {
214	                channel.close();
215	                promise.tryFailure(cause);
216	                return promise;
217	            }
218	
219	            if (!resolver.isSupported(remoteAddress) || resolver.isResolved(remoteAddress)) {
220	                // Resolver has no idea about what to do with the specified remote address or it's resolved already.
221	                doConnect(remoteAddress, localAddress, promise);
222	                return promise;
223	            }
224	
225	            final Future<SocketAddress> resolveFuture = resolver.resolve(remoteAddress);
226	
227	            if (resolveFuture.isDone()) {
228	                final Throwable resolveFailureCause = resolveFuture.cause();
229	
230	                if (resolveFailureCause != null) {
231	                    // Failed to resolve immediately
232	                    channel.close();
233	                    promise.tryFailure(resolveFailureCause);
234	                } else {
235	                    // Succeeded to resolve immediately; cached? (or did a blocking lookup)
236	                    doConnect(resolveFuture.getNow(), localAddress, promise);
237	                }
238	                return promise;
239	            }
240	
241	            // Wait until the name resolution is finished.
242	            resolveFuture.addListener((FutureListener<SocketAddress>) future -> {
243	                Throwable cause = future.cause();
244	                if (cause != null) {
245	                    channel.close();
246	                    promise.tryFailure(cause);
247	                } else if (!promise.isDone()) {
248	                    doConnect(future.getNow(), localAddress, promise);
249	                }
250	            });
251	        } catch (Throwable cause) {
252	            promise.tryFailure(cause);
253	        }
254	        return promise;
255	    }
256	
257	    private static void doConnect(
258	            final SocketAddress remoteAddress, final SocketAddress localAddress, final ChannelPromise connectPromise) {
259	
260	        // This method is invoked before channelRegistered() is triggered.  Give user handlers a chance to set up
261	        // the pipeline in its channelRegistered() implementation.
262	        final Channel channel = connectPromise.channel();
263	        channel.eventLoop().execute(new Runnable() {
264	            @Override
265	            public void run() {
266	                if (localAddress == null) {
267	                    channel.connect(remoteAddress, connectPromise);
268	                } else {
269	                    channel.connect(remoteAddress, localAddress, connectPromise);
270	                }
271	            }
272	        });
273	    }
274	
275	    @Override
276	    void init(Channel channel) throws Throwable {
277	        ChannelPipeline p = channel.pipeline();
278	        p.addLast(config.handler());
279	
280	        setChannelOptions(channel, newOptionsArray(), logger);
281	
282	        setAttributes(channel, newAttributesArray());
283	        Collection<ChannelInitializerExtension> extensions = getInitializerExtensions();
284	        if (!extensions.isEmpty()) {
285	            for (ChannelInitializerExtension extension : extensions) {
286	                try {
287	                    extension.postInitializeClientChannel(channel);
288	                } catch (Exception e) {
289	                    logger.warn("Exception thrown from postInitializeClientChannel", e);
290	                }
291	            }
292	        }
293	    }
294	
295	    @Override
296	    public Bootstrap validate() {
297	        super.validate();
298	        if (config.handler() == null) {
299	            throw new IllegalStateException("handler not set");
300	        }
301	        return this;
302	    }
303	
304	    @Override
305	    @SuppressWarnings("CloneDoesntCallSuperClone")
306	    public Bootstrap clone() {
307	        return new Bootstrap(this);
308	    }
309	
310	    /**
311	     * Returns a deep clone of this bootstrap which has the identical configuration except that it uses
312	     * the given {@link EventLoopGroup}. This method is useful when making multiple {@link Channel}s with similar
313	     * settings.
314	     */
315	    public Bootstrap clone(EventLoopGroup group) {
316	        Bootstrap bs = new Bootstrap(this);
317	        bs.group = group;
318	        return bs;
319	    }
320	
321	    @Override
322	    public final BootstrapConfig config() {
323	        return config;
324	    }
325	
326	    final SocketAddress remoteAddress() {
327	        return remoteAddress;
328	    }
329	
330	    final AddressResolverGroup<?> resolver() {
331	        if (disableResolver) {
332	            return null;
333	        }
334	        return ExternalAddressResolver.getOrDefault(externalResolver);
335	    }
336	
337	    /* Holder to avoid NoClassDefFoundError in case netty-resolver dependency is excluded
338	       (e.g. some address families do not need name resolution) */
339	    static final class ExternalAddressResolver {
340	        final AddressResolverGroup<SocketAddress> resolverGroup;
341	
342	        @SuppressWarnings("unchecked")
343	        ExternalAddressResolver(AddressResolverGroup<?> resolverGroup) {
344	            this.resolverGroup = (AddressResolverGroup<SocketAddress>) resolverGroup;
345	        }
346	
347	        @SuppressWarnings("unchecked")
348	        static AddressResolverGroup<SocketAddress> getOrDefault(ExternalAddressResolver externalResolver) {
349	            if (externalResolver == null) {
350	                AddressResolverGroup<?> defaultResolverGroup = DefaultAddressResolverGroup.INSTANCE;
351	                return (AddressResolverGroup<SocketAddress>) defaultResolverGroup;
352	            }
353	            return externalResolver.resolverGroup;
354	        }
355	    }
356	}
